#[test]
fn a_helper_over_the_memory_cap_is_restarted() {
    let fake = Fake::new(
        "memory",
        r#"
rec(b"REDY")
for n in range(100000):
    frame(w, h, 1); time.sleep(1 / 30)
"#,
    );
    let seen = Arc::new(Seen::default());
    let (capture, _, _) = start_fake(&fake, &seen, false).unwrap();
    fake.memory
        .store(timing().memory_cap_mb + 1, Ordering::SeqCst);
    wait_for("the restart", 10, || capture.restarts() >= 1);
    fake.memory.store(1, Ordering::SeqCst);
    assert!(seen.stopped.lock().unwrap().is_none());
}

#[test]
fn a_frame_pool_that_keeps_failing_stops_the_source_with_why() {
    // A failed GPU upload leaves a pool unusable: the source gets new pools
    // (restarting the helper, whose stream broke mid-picture) a few times,
    // then stops with the reason instead of restarting forever.
    let fake = Fake::new(
        "pool",
        r#"
rec(b"REDY")
for n in range(100000):
    frame(w, h, 1); time.sleep(1 / 30)
"#,
    );
    let seen = Arc::new(Seen::default());
    let (video, _) = sinks(&seen);
    let (capture, _, _) = start(
        fake.os(),
        timing(),
        &page(),
        pools(&seen, true),
        video,
        None,
    )
    .unwrap();
    wait_for("the source to stop", 15, || {
        seen.stopped.lock().unwrap().is_some()
    });
    let why = seen.stopped.lock().unwrap().clone().unwrap();
    assert!(
        why.contains("couldn't be stored 3 times") && why.contains("failed upload"),
        "{why}"
    );
    assert_eq!(
        seen.pools.load(Ordering::SeqCst),
        3,
        "the first pool and two new ones"
    );
    assert_eq!(capture.restarts(), 2);
    assert_eq!(seen.frames.load(Ordering::SeqCst), 0);
}

#[test]
fn stopping_during_a_slow_restart_returns_at_once() {
    // A restarted helper that never says it's loading would hold the source
    // thread for the whole start timeout; dropping the source must not.
    let fake = Fake::new(
        "slow-restart",
        r#"
if starts > 0:
    time.sleep(3600)
rec(b"REDY")
frame(w, h, 1)
os._exit(1)
"#,
    );
    let seen = Arc::new(Seen::default());
    let (capture, _, _) = start_fake(&fake, &seen, false).unwrap();
    wait_for("the second start", 10, || fake.starts() >= 2);
    let dropped = Instant::now();
    drop(capture);
    assert!(
        dropped.elapsed() < Duration::from_secs(2),
        "drop took {:?}",
        dropped.elapsed()
    );
}

#[test]
fn a_refreshed_page_starts_the_hang_clock_again() {
    // Refresh halfway through the 800 ms timeout. The next picture arrives
    // past the original deadline but comfortably within the refreshed one.
    let fake = Fake::new(
        "refresh",
        r#"
rec(b"REDY")
frame(w, h, 1)
for line in sys.stdin:
    if line.strip() == "reload":
        time.sleep(0.55)
        for n in range(1000):
            frame(w, h, 2); time.sleep(1 / 30)
"#,
    );
    let seen = Arc::new(Seen::default());
    let (capture, _, control) = start_fake(&fake, &seen, false).unwrap();
    wait_for("the first picture", 10, || {
        seen.frames.load(Ordering::SeqCst) >= 1
    });
    std::thread::sleep(timing().hang / 2);
    control.refresh();
    wait_for("pictures after the reload", 10, || {
        seen.first_byte.lock().unwrap().contains(&2)
    });
    assert_eq!(capture.restarts(), 0, "a refresh isn't a hang");
    assert_eq!(fake.starts(), 1);
}

//! The Windows part of browser sources: the kill-on-close job and the
//! advice. The host's process handling (crash, hang, restart, sizes, pools)
//! is tested in crates/isocast-browser-host; the real helper runs in the
//! e2e scenario `win_browser`.

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use isocast_engine::PageLocation;
use windows::Win32::Foundation::STILL_ACTIVE;
use windows::Win32::System::Threading::GetExitCodeProcess;

use super::*;

fn python() -> PathBuf {
    std::env::var_os("PYTHON").map_or_else(|| "python".into(), PathBuf::from)
}

fn alive(pid: u32) -> bool {
    let Ok(process) = (unsafe { OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, false, pid) })
    else {
        return false;
    };
    let mut code = 0u32;
    let running =
        unsafe { GetExitCodeProcess(process, &mut code) }.is_ok() && code == STILL_ACTIVE.0 as u32;
    let _ = unsafe { CloseHandle(process) };
    running
}

fn wait_for(what: &str, seconds: u64, ok: impl Fn() -> bool) {
    let deadline = Instant::now() + Duration::from_secs(seconds);
    while !ok() {
        assert!(Instant::now() < deadline, "timed out waiting for {what}");
        std::thread::sleep(Duration::from_millis(20));
    }
}

#[test]
fn a_missing_runtime_names_where_to_get_it() {
    let text = explain_start_failure(
        Some(3),
        Some(
            "browser sources need the Microsoft Edge WebView2 Runtime, which isn't installed: \
             get it from https://go.microsoft.com/fwlink/p/?LinkId=2124703",
        ),
        "",
    );
    assert!(text.contains("go.microsoft.com/fwlink"), "{text}");
    let text = explain_start_failure(Some(0xC000_0135_u32 as i32), None, "");
    assert!(text.contains("reinstall Isocast"), "{text}");
    let text = explain_start_failure(Some(7), None, "something went wrong\n");
    assert!(
        text.contains("status 0x7") && text.contains("something went wrong"),
        "{text}"
    );
}

#[test]
fn memory_of_a_job_counts_its_processes() {
    let job = Job::new().unwrap();
    let mut child = Command::new(python())
        .args(["-c", "import time; time.sleep(10)"])
        .creation_flags(CREATE_NO_WINDOW.0)
        .spawn()
        .unwrap();
    assert_eq!(job.memory_mb(), 0, "an empty job");
    unsafe { AssignProcessToJobObject(*job.0, HANDLE(child.as_raw_handle())) }.unwrap();
    wait_for("the child's working set", 10, || job.memory_mb() > 0);
    job.kill();
    let _ = child.wait();
}

/// CPU frames, for a source without a GPU.
struct Pool;

impl FramePool for Pool {
    type Frame = Vec<u8>;
    fn draw(&mut self, draw: &mut dyn FnMut(&mut [u8], usize)) -> Result<Option<Vec<u8>>> {
        let mut pixels = vec![0u8; 8 * 4 * 4];
        draw(&mut pixels, 8 * 4);
        Ok(Some(pixels))
    }
    fn take(&mut self) -> Result<Option<Vec<u8>>> {
        Ok(None)
    }
}

#[test]
fn an_unresponsive_helper_fails_instead_of_opening_a_blank_source() {
    let helper = Helper {
        program: python(),
        prefix: vec!["-c".into(), "import time; time.sleep(60)".into()],
    };
    let failure = isocast_browser_host::start(
        Arc::new(helper),
        Timing {
            start: Duration::from_secs(1),
            ..Timing::default()
        },
        &BrowserPage {
            location: PageLocation::Url("about:blank"),
            width: 8,
            height: 4,
            fps: 30,
            css: "",
        },
        || Ok(Pool),
        VideoSink {
            frame: Box::new(|_, _| panic!("hung helper sent a frame")),
            stopped: Box::new(|_| {}),
        },
        None,
    )
    .err()
    .expect("a helper that never reports ready must fail");
    assert!(
        failure
            .to_string()
            .contains("didn't start the page within 1 s"),
        "{failure:#}"
    );
}

#[test]
fn the_helpers_own_processes_end_with_the_source() {
    // WebView2's browser processes are the helper's children: they share
    // its job and end with it, even if the helper never cleans up.
    let dir = std::env::temp_dir().join(format!("isocast-browser-job-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let script = dir.join("helper.py");
    std::fs::write(
        &script,
        r#"
import os, struct, subprocess, sys, time
out = sys.stdout.buffer
def rec(tag, payload=b""):
    out.write(tag + struct.pack("<I", len(payload)) + payload); out.flush()
sys.stdin.readline()
here = os.path.dirname(os.path.abspath(__file__))
child = subprocess.Popen([sys.executable, "-c", "import time; time.sleep(3600)"])
open(os.path.join(here, "child"), "w").write(str(child.pid))
rec(b"REDY")
while True:
    rec(b"FRAM", struct.pack("<II", 8, 4) + bytes(8 * 4 * 4)); time.sleep(1 / 30)
"#,
    )
    .unwrap();
    let helper = Helper {
        program: python(),
        prefix: vec!["-u".into(), script.to_string_lossy().into_owned()],
    };
    let frames = Arc::new(AtomicUsize::new(0));
    let stopped = Arc::new(Mutex::new(None::<String>));
    let (f, s) = (frames.clone(), stopped.clone());
    let sink = VideoSink {
        frame: Box::new(move |_: Vec<u8>, _| {
            f.fetch_add(1, Ordering::SeqCst);
        }),
        stopped: Box::new(move |why| *s.lock().unwrap() = Some(why)),
    };
    let page = BrowserPage {
        location: PageLocation::Url("http://example.invalid/"),
        width: 8,
        height: 4,
        fps: 30,
        css: "",
    };
    let (capture, _, _) = start(helper, &page, || Ok(Pool), sink, None).unwrap();
    let child = dir.join("child");
    wait_for("the child", 10, || {
        child.exists() && frames.load(Ordering::SeqCst) > 0
    });
    let pid: u32 = std::fs::read_to_string(&child)
        .unwrap()
        .trim()
        .parse()
        .unwrap();
    assert!(alive(pid), "the helper's child runs");
    drop(capture);
    wait_for("the child to end", 10, || !alive(pid));
    assert!(stopped.lock().unwrap().is_none());
    let _ = std::fs::remove_dir_all(&dir);
}

//! Browser sources against fake helpers (Python scripts that speak the
//! helper's protocol), so the process handling, restarts and limits are
//! tested without WebKit. The real helper runs in the e2e scenario.

use std::sync::atomic::AtomicUsize;

use super::*;

/// A fake helper: Python with `struct`, writing records to stdout.
const PRELUDE: &str = r#"
import os, struct, sys, time
out = sys.stdout.buffer
def rec(tag, payload=b""):
    out.write(tag + struct.pack("<I", len(payload)) + payload); out.flush()
def frame(w, h, value):
    rec(b"FRAM", struct.pack("<II", w, h) + bytes([value]) * (w * h * 4))
args = sys.argv[1:]
w = int(args[args.index("--width") + 1]); h = int(args[args.index("--height") + 1])
state = os.environ["FAKE_STATE"]
here = os.path.dirname(state)
open(os.path.join(here, "page"), "w").write(sys.stdin.readline())
open(os.path.join(here, "argv"), "w").write(" ".join(args))
starts = int(open(state).read()) if os.path.exists(state) else 0
open(state, "w").write(str(starts + 1))
"#;

struct Fake {
    dir: PathBuf,
}

impl Fake {
    fn new(name: &str, body: &str) -> Self {
        let dir = std::env::temp_dir().join(format!(
            "isocast-browser-test-{name}-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let script = dir.join("helper.py");
        let state = dir.join("state");
        std::fs::write(
            &script,
            format!(
                "#!/usr/bin/env -S FAKE_STATE={} python3\n{PRELUDE}{body}",
                state.display()
            ),
        )
        .unwrap();
        // A parallel fork can inherit our writable fd even after we close it.
        // Have install own the executable's writer; a rename would keep the inode.
        assert!(
            Command::new("install")
                .args(["-m", "755"])
                .arg(&script)
                .arg(dir.join("helper"))
                .status()
                .unwrap()
                .success()
        );
        Self { dir }
    }

    fn path(&self) -> PathBuf {
        self.dir.join("helper")
    }

    fn starts(&self) -> usize {
        std::fs::read_to_string(self.dir.join("state")).map_or(0, |s| s.trim().parse().unwrap_or(0))
    }

    fn file(&self, name: &str) -> String {
        std::fs::read_to_string(self.dir.join(name)).unwrap_or_default()
    }
}

impl Drop for Fake {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

#[derive(Default)]
struct Seen {
    frames: AtomicUsize,
    first_byte: Mutex<Vec<u8>>,
    audio_frames: AtomicUsize,
    stopped: Mutex<Option<String>>,
}

fn sinks(seen: &Arc<Seen>) -> (VideoSink<Frame>, AudioSink) {
    let (a, b, c, d) = (seen.clone(), seen.clone(), seen.clone(), seen.clone());
    (
        VideoSink {
            frame: Box::new(move |frame: Frame, _| {
                a.frames.fetch_add(1, Ordering::SeqCst);
                a.first_byte
                    .lock()
                    .unwrap()
                    .push(frame.read_bgra().unwrap()[0]);
            }),
            stopped: Box::new(move |why| *b.stopped.lock().unwrap() = Some(why)),
        },
        AudioSink {
            report_gap: Box::new(|_, gap| panic!("unexpected browser gap: {gap:?}")),
            samples: Box::new(move |samples, _| {
                c.audio_frames
                    .fetch_add(samples.len() / 2, Ordering::SeqCst);
            }),
            stopped: Box::new(move |why| *d.stopped.lock().unwrap() = Some(why)),
        },
    )
}

fn unhex(word: &str) -> String {
    let bytes: Vec<u8> = (0..word.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&word[i..i + 2], 16).unwrap())
        .collect();
    String::from_utf8(bytes).unwrap()
}

fn page() -> BrowserPage<'static> {
    BrowserPage {
        location: PageLocation::Url("http://example.invalid/"),
        width: 8,
        height: 4,
        fps: 30,
        css: "",
    }
}

fn wait_for(what: &str, seconds: u64, ok: impl Fn() -> bool) {
    let deadline = Instant::now() + Duration::from_secs(seconds);
    while !ok() {
        assert!(Instant::now() < deadline, "timed out waiting for {what}");
        std::thread::sleep(Duration::from_millis(20));
    }
}

#[test]
fn protocol_reads_each_record_and_rejects_bad_ones() {
    let mut bytes = Vec::new();
    bytes.extend(b"REDY\0\0\0\0");
    bytes.extend(b"FRAM");
    bytes.extend(&(8u32 + 2 * 4).to_le_bytes());
    bytes.extend(&2u32.to_le_bytes());
    bytes.extend(&1u32.to_le_bytes());
    let pixels_at = bytes.len();
    bytes.extend([7u8; 8]);
    bytes.extend(b"AUDI");
    bytes.extend(&(4u32 + 8).to_le_bytes());
    bytes.extend(&44100u32.to_le_bytes());
    bytes.extend([0u8; 8]);
    let mut input = &bytes[..];
    assert_eq!(
        protocol::read_header(&mut input).unwrap(),
        Some(protocol::Header::Ready)
    );
    assert_eq!(
        protocol::read_header(&mut input).unwrap(),
        Some(protocol::Header::Frame {
            width: 2,
            height: 1
        })
    );
    assert_eq!(bytes.len() - input.len(), pixels_at);
    input = &input[8..];
    assert_eq!(
        protocol::read_header(&mut input).unwrap(),
        Some(protocol::Header::Audio {
            rate: 44100,
            len: 8
        })
    );
    input = &input[8..];
    assert_eq!(protocol::read_header(&mut input).unwrap(), None);

    let mut timed = b"AUDT".to_vec();
    timed.extend(&21u32.to_le_bytes());
    timed.extend(&48000u32.to_le_bytes());
    timed.push(1);
    timed.extend(&75_000u64.to_le_bytes());
    timed.extend([0u8; 8]);
    let mut timed_slice = &timed[..];
    assert_eq!(
        protocol::read_header(&mut timed_slice).unwrap(),
        Some(protocol::Header::TimedAudio {
            rate: 48000,
            resumed: true,
            end_us: 75_000,
            len: 8,
        })
    );
    timed[12] = 2;
    assert!(protocol::read_header(&mut &timed[..]).is_err());

    // A picture whose size doesn't match its length, an oversized record,
    // and an unknown tag are errors, not guesses.
    let mut bad = b"FRAM".to_vec();
    bad.extend(&100u32.to_le_bytes());
    bad.extend(&2u32.to_le_bytes());
    bad.extend(&1u32.to_le_bytes());
    assert!(protocol::read_header(&mut &bad[..]).is_err());
    let mut huge = b"FRAM".to_vec();
    huge.extend(&u32::MAX.to_le_bytes());
    assert!(protocol::read_header(&mut &huge[..]).is_err());
    assert!(protocol::read_header(&mut &b"WHAT\0\0\0\0"[..]).is_err());
}

fn audio_record(rate: u32, bytes: usize) -> Vec<u8> {
    let mut record = b"AUDI".to_vec();
    record.extend(&(4 + bytes as u32).to_le_bytes());
    record.extend(&rate.to_le_bytes());
    record.extend(vec![0u8; bytes]);
    record
}

#[test]
fn protocol_refuses_audio_rates_and_sizes_a_page_could_abuse() {
    // A page picks the rate (audio.js): resampling 1 Hz to 48 kHz would
    // ask for 48,000 times the input. Only 8–192 kHz pass.
    for rate in [0, 1, 7_999, 192_001, u32::MAX] {
        let err = protocol::read_header(&mut &audio_record(rate, 8)[..]).unwrap_err();
        assert!(err.to_string().contains("Hz"), "{rate}: {err:#}");
    }
    for rate in [8_000, 44_100, 48_000, 192_000] {
        assert_eq!(
            protocol::read_header(&mut &audio_record(rate, 8)[..]).unwrap(),
            Some(protocol::Header::Audio { rate, len: 8 })
        );
    }
    // Audio and failure reasons have small caps, not the picture's.
    let mut huge_audio = b"AUDI".to_vec();
    huge_audio.extend(&(4 + protocol::MAX_AUDIO + 8).to_le_bytes());
    assert!(protocol::read_header(&mut &huge_audio[..]).is_err());
    let mut huge_fail = b"FAIL".to_vec();
    huge_fail.extend(&(protocol::MAX_FAIL + 1).to_le_bytes());
    assert!(protocol::read_header(&mut &huge_fail[..]).is_err());
    assert!(protocol::read_header(&mut &b"REDY\x01\0\0\0"[..]).is_err());
    // And the resampler never sizes a buffer from a refused rate.
    assert!(Resampler::default().run(1, vec![0.0; 960]).is_empty());
}

